import sys

class Solution:

	def cutRod(self, price, n):
		N = n
		cur = [0] * (N + 1)
		for i in range(N + 1):
			cur[i] = i * price[0]
		for ind in range(1, N):
			for length in range(N + 1):
				notTaken = 0 + cur[length]
				taken = float('-inf')
				rodLength = ind + 1
				if rodLength <= length:
					taken = price[ind] + cur[length - rodLength]
				cur[length] = max(notTaken, taken)
		return cur[N]
